{
  "API_calls": [],
  "collected_information": {
    "pyproject.toml": {
      "project_version": "1.8.0",
      "extras": [
        "docling",
        "audio",
        "couchbase",
        "cassio",
        "local",
        "clickhouse-connect",
        "nv-ingest",
        "postgresql"
      ],
      "dev_dependencies": [
        "pytest",
        "pytest-asyncio",
        "pre-commit",
        "mypy",
        "httpx"
      ]
    },
    "README.md": {
      "python_version": "3.10 to 3.13",
      "package_manager": "uv",
      "local_install_command": "uv pip install langflow -U",
      "run_command": "uv run langflow run",
      "run_from_source_command": "make run_cli",
      "version_warnings": [
        "Avoid Langflow versions 1.6.0–1.6.3 and 1.7.0 due to bugs"
      ],
      "reference": "DEVELOPMENT.md for detailed dev instructions"
    },
    "CONTRIBUTING.md": {
      "reference": "DEVELOPMENT.md for detailed dev environment setup"
    },
    "DEVELOPMENT.md": {
      "os_supported": ["macOS", "Linux", "Windows with WSL or Dev Container"],
      "requirements": ["git", "make", "uv >=0.4", "Node.js v22.12 LTS", "npm v10.9"],
      "setup_steps": [
        "make init (installs backend and frontend dependencies and pre-commit hooks)",
        "make backend",
        "make frontend",
        "make unit_tests",
        "uv run pytest <test_file_path>",
        "uv run pre-commit install"
      ]
    },
    "docker/dev.Dockerfile": {
      "base_image": "ghcr.io/astral-sh/uv:python3.12-bookworm-slim",
      "apt_packages": ["build-essential", "curl", "npm", "git"],
      "dependency_install_command": "uv sync --frozen --no-install-project --no-dev --extra postgresql",
      "working_directory": "/app",
      "timezone": "UTC"
    },
    "docker_example/Dockerfile": {
      "base_image": "langflowai/langflow:latest",
      "run_command": "python -m langflow run --host 0.0.0.0 --port 7860"
    },
    "tests": {
      "test_command_example": "uv run pytest src/backend/tests/unit/test_database.py"
    },
    "notes": {
      "no_requirements_test_txt": "pyproject.toml dev group is definitive source for dev dependencies",
      "ci_workflows": "Present but no detailed extraction done; likely use 'uv' and make targets"
    }
  },
  "terminate": true
}
